Here's a complete, runnable p5.js sketch that renders a rotating 4D tesseract projected to 2D. It includes the 4D rotation matrices, perspective projection, and edge list, ready to paste into the p5.js web editor.
```js
/* ============================================================================
   Rotating tesseract (4D hypercube) projected to 2D — self-contained p5.js
   ============================================================================
   Pipeline per frame:
     1. 16 vertices of the hypercube {-1,+1}^4          (V4)
     2. four independent 4D rotations, one per plane    (rot4)
     3. 4D -> 3D perspective projection                 (project4to3)
     4. 3D -> 2D perspective projection                 (project3to2)
     5. painter's-algorithm edge rendering with depth colouring
   ============================================================================ */

// --- Camera / projection constants ------------------------------------------
const DIST4 = 3.0;   // 4D camera distance along the w axis
const DIST3 = 4.0;   // 3D camera distance along the z axis
const N = 16;        // 2^4 vertices

let V4 = [];         // vertex array: [x, y, z, w]
let EDGES = [];      // edge array: pairs of vertex indices

// ---------------------------------------------------------------------------
function setup() {
  createCanvas(windowWidth, windowHeight);
  buildTesseract();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// ---------------------------------------------------------------------------
// Vertex list: index i encodes the sign of each coordinate in its 4 bits.
// Edge list: two vertices are adjacent iff their indices differ in exactly
// one bit (XOR is a power of two) -> 32 edges.
// ---------------------------------------------------------------------------
function buildTesseract() {
  V4 = [];
  for (let i = 0; i < N; i++) {
    V4.push([
      (i & 1) ? 1 : -1,   // x
      (i & 2) ? 1 : -1,   // y
      (i & 4) ? 1 : -1,   // z
      (i & 8) ? 1 : -1    // w
    ]);
  }

  EDGES = [];
  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      const d = i ^ j;
      if ((d & (d - 1)) === 0) EDGES.push([i, j]); // exactly one bit set
    }
  }
}

// ---------------------------------------------------------------------------
// 4D rotation in the plane spanned by axes (a, b):
//
//   R = identity except
//   R[a][a] =  cos t    R[a][b] = -sin t
//   R[b][a] =  sin t    R[b][b] =  cos t
// ---------------------------------------------------------------------------
function rot4(v, a, b, angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  const out = v.slice();
  out[a] = v[a] * c - v[b] * s;
  out[b] = v[a] * s + v[b] * c;
  return out;
}

// ---------------------------------------------------------------------------
// 4D -> 3D perspective projection along w.
//   k = D / (D - w),   (x, y, z, w) -> (x*k, y*k, z*k)
// ---------------------------------------------------------------------------
function project4to3(v) {
  const k = DIST4 / (DIST4 - v[3]);
  return [v[0] * k, v[1] * k, v[2] * k];
}

// ---------------------------------------------------------------------------
// 3D -> 2D perspective projection along z.
//   k = D / (D - z),   (x, y, z) -> (x*k, y*k)
// ---------------------------------------------------------------------------
function project3to2(p) {
  const k = DIST3 / (DIST3 - p[2]);
  return [p[0] * k, p[1] * k];
}

// ---------------------------------------------------------------------------
function draw() {
  background(6, 8, 14);
  const t = millis() * 0.001;

  // Four independent rotation angles (XW, YZ, XY, ZW planes).
  const aXW = t * 0.63;
  const aYZ = t * 0.41;
  const aXY = t * 0.29;
  const aZW = t * 0.53;

  // --- Rotate + project ----------------------------------------------------
  const P3 = [];   // projected 3D points (used for depth sorting / shading)
  const P2 = [];   // projected 2D points

  for (let i = 0; i < N; i++) {
    let v = V4[i].slice();
    v = rot4(v, 0, 3, aXW);  // x–w plane
    v = rot4(v, 1, 2, aYZ);  // y–z plane
    v = rot4(v, 0, 1, aXY);  // x–y plane
    v = rot4(v, 2, 3, aZW);  // z–w plane

    const p3 = project4to3(v);
    P3.push(p3);
    P2.push(project3to2(p3));
  }

  // --- Map to screen space -------------------------------------------------
  const S = Math.min(width, height) * 0.17;
  const cx = width * 0.5;
  const cy = height * 0.5;

  const screenPts = P2.map(p => ({
    x: cx + p[0] * S,
    y: cy - p[1] * S
  }));

  // --- Depth range for colour / weight mapping -----------------------------
  let minZ = Infinity;
  let maxZ = -Infinity;
  for (const p of P3) {
    if (p[2] < minZ) minZ = p[2];
    if (p[2] > maxZ) maxZ = p[2];
  }
  const span = Math.max(1e-6, maxZ - minZ);

  const cFar = color(38, 66, 158);
  const cNear = color(140, 240, 255);

  // --- Painter's algorithm: farthest edges first ---------------------------
  const order = EDGES
    .map(e => ({ e: e, z: (P3[e[0]][2] + P3[e[1]][2]) * 0.5 }))
    .sort((p, q) => p.z - q.z);

  drawingContext.shadowBlur = 14;
  drawingContext.shadowColor = 'rgba(90, 190, 255, 0.85)';
  strokeCap(ROUND);
  noFill();

  for (const item of order) {
    const i = item.e[0];
    const j = item.e[1];
    const nz = (item.z - minZ) / span;          // 0 = far, 1 = near

    stroke(lerpColor(cFar, cNear, nz * nz));
    strokeWeight(0.8 + 2.6 * nz);
    line(screenPts[i].x, screenPts[i].y, screenPts[j].x, screenPts[j].y);
  }

  // --- Vertices ------------------------------------------------------------
  noStroke();
  drawingContext.shadowBlur = 18;
  drawingContext.shadowColor = 'rgba(180, 240, 255, 0.9)';

  for (let i = 0; i < N; i++) {
    const nz = (P3[i][2] - minZ) / span;
    fill(lerpColor(cFar, cNear, nz));
    const r = 1.8 + 3.4 * nz;
    circle(screenPts[i].x, screenPts[i].y, r * 2);
  }

  drawingContext.shadowBlur = 0;
}
```
### Rendering Pipeline & Interaction

This sketch turns a 4D hypercube into an animated 2D line drawing by chaining rotations, projections, and depth-based coloring.

- **Vertex and edge generation** – The 16 vertices are all sign combinations of four coordinates (±1), and each edge connects two vertices whose indices differ by exactly one bit (XOR is a power of two).
- **Four-plane rotation** – Each frame applies independent rotations in the XW, YZ, XY, and ZW planes using `rot4`, giving the tesseract its characteristic twisting motion.
- **Dual perspective projection** – First `project4to3` maps 4D points to 3D using a perspective divide along w, then `project3to2` maps 3D to 2D along z, producing the final screen positions.
- **Depth-based rendering** – Edges are sorted far-to-near, with stroke color and weight interpolated by projected depth; vertices are drawn as glowing circles with similar depth shading.
